1|// Pure chat contract shared by the route and the panel. No env reads,
2|// no network, no secrets. Server modules in server/chat/ build on it.
3|
4|export const CHAT_DAILY_LIMIT = 15;
5|// Abuse ceiling for requests paid with the reader's own key.
6|export const CHAT_BYOK_DAILY_LIMIT = 200;
7|export const CHAT_MAX_QUESTION_CHARS = 500;
8|// Earlier turns kept as conversation memory, user and assistant together.
9|export const CHAT_MAX_MESSAGES = 6;
10|export const CHAT_MAX_ANSWER_CHARS = 4000;
11|export const CHAT_MAX_BODY_BYTES = 16_384;
12|export const CHAT_MAX_TOKENS = 400;
13|export const CHAT_MODEL = "muse-spark-1.3";
14|export const BYOK_HEADER = "x-byok-key";
15|
16|export type ChatRole = "user" | "assistant";
17|
18|export interface ChatMessage {
19|  role: ChatRole;
20|  content: string;
21|}
22|
23|// The client sends a position, never book text: the server builds the context.
24|export interface ChatRequest {
25|  bookId: "oz";
26|  // Global paragraph ordinal of the last paragraph the reader has reached.
27|  upToN: number;
28|  spoilers: boolean;
29|  // Oldest first, last one is the new user question.
30|  messages: ChatMessage[];
31|  turnstileToken?: string;
32|}
33|
34|export type ChatErrorCode =
35|  | "bad_request"
36|  | "too_large"
37|  | "human"
38|  | "quota"
39|  | "byok_required"
40|  | "unavailable";
41|
42|export interface ChatErrorBody {
43|  status: "error";
44|  code: ChatErrorCode;
45|  message: string;
46|}
47|
48|// Server-sent events on success (text/event-stream):
49|//   event: delta  data: {"text": "..."}
50|//   event: done   data: {"remaining": 12}   (remaining omitted under BYOK)
51|//   event: error  data: {"code": "unavailable", "message": "..."}
52|export type ChatStreamEvent =
53|  | { event: "delta"; data: { text: string } }
54|  | { event: "done"; data: { remaining?: number } }
55|  | { event: "error"; data: { code: "unavailable"; message: string } };
56|
57|// Fixed copy. Clients map `code` to their own state; this is the fallback.
58|export const CHAT_MESSAGES: Record<ChatErrorCode, string> = {
59|  bad_request: "Something went wrong there. Try again?",
60|  too_large: "That question is a little long. Try a shorter one?",
61|  human: "One quick check that you're a person.",
62|  quota: "That's 15 questions for today. They come back tomorrow, and the book is always here.",
63|  byok_required: "Our free questions are used up for now. With your Meta key you can keep asking.",
64|  unavailable: "Something went wrong on our side. Your question is safe, try again in a moment.",
65|};
66|
67|export const HTTP_STATUS: Record<ChatErrorCode, number> = {
68|  bad_request: 400,
69|  too_large: 413,
70|  human: 403,
71|  quota: 429,
72|  byok_required: 503,
73|  unavailable: 503,
74|};

