1|import { useId, useState } from "react";
2|import { approxPages, FREE_BOOK_MAX_WORDS } from "@/core/upload-policy";
3|
4|type Provider = "meta" | "openai";
5|
6|const REASONS: Record<"too_long" | "free_used", (pages: number) => string> = {
7|  too_long: (pages) => `This one is longer than about ${pages} pages, so it needs your own key.`,
8|  free_used: () => "You've already used your free book, so this one needs your own key.",
9|};
10|
11|// Key step only: no network call. The key lives in state and is cleared
12|// on submit, on reset, and on unmount; never stored, logged, or shared.
13|export function ByokStep({
14|  reason,
15|  initialKey,
16|  onSubmit,
17|}: {
18|  reason: "too_long" | "free_used";
19|  initialKey?: string;
20|  onSubmit: () => void;
21|}) {
22|  const [provider, setProvider] = useState<Provider>("meta");
23|  const [key, setKey] = useState(initialKey ?? "");
24|  const [baseUrl, setBaseUrl] = useState("");
25|  const [model, setModel] = useState("");
26|  const privacyId = useId();
27|  const urlId = useId();
28|  const urlErrorId = useId();
29|  const freePages = approxPages(FREE_BOOK_MAX_WORDS);
30|
31|  const urlOk = baseUrl.trim() === "" || /^https:\/\//.test(baseUrl.trim());
32|  const ready =
33|    key.trim() !== "" && (provider === "meta" || (urlOk && baseUrl.trim() !== "" && model.trim() !== ""));
34|
35|  return (
36|    <div>
37|      <h3 className="ob-byok-t">Bring your own key!</h3>
38|      <p className="ob-note">{REASONS[reason](freePages)}</p>
39|      <div className="ob-radio-row" role="radiogroup" aria-label="Key provider">
40|        <label className="ob-radio">
41|          <input
42|            type="radio"
43|            name="byok-provider"
44|            checked={provider === "meta"}
45|            onChange={() => setProvider("meta")}
46|          />
47|          Meta <span className="ob-tag">Recommended</span>
48|        </label>
49|        <label className="ob-radio">
50|          <input
51|            type="radio"
52|            name="byok-provider"
53|            checked={provider === "openai"}
54|            onChange={() => setProvider("openai")}
55|          />
56|          OpenAI-compatible
57|        </label>
58|      </div>
59|      {provider === "openai" && (
60|        <>
61|          <label className="ob-field" htmlFor={urlId}>
62|            Base URL
63|            <input
64|              id={urlId}
65|              className="ob-input"
66|              type="url"
67|              value={baseUrl}
68|              onChange={(event) => setBaseUrl(event.target.value)}
69|              placeholder="https://"
70|              aria-invalid={!urlOk}
71|              aria-describedby={urlOk ? undefined : urlErrorId}
72|            />
73|          </label>
74|          {!urlOk && (
75|            <p className="ob-error" id={urlErrorId}>
76|              The base URL needs to start with https://.
77|            </p>
78|          )}
79|          <label className="ob-field">
80|            Model
81|            <input
82|              className="ob-input"
83|              value={model}
84|              onChange={(event) => setModel(event.target.value)}
85|            />
86|          </label>
87|        </>
88|      )}
89|      <label className="ob-field">
90|        Key
91|        <input
92|          className="ob-input"
93|          type="password"
94|          name="transient-key"
95|          autoComplete="off"
96|          spellCheck={false}
97|          value={key}
98|          onChange={(event) => setKey(event.target.value)}
99|          aria-describedby={privacyId}
100|        />
101|      </label>
102|      <p className="ob-note" id={privacyId}>
103|        Your key stays in this browser tab. It&apos;s never stored on our servers, and it&apos;s
104|        only used to process this book.
105|      </p>
106|      <div className="ob-actions">
107|        <button
108|          className="ob-action"
109|          type="button"
110|          disabled={!ready}
111|          onClick={() => {
112|            setKey("");
113|            onSubmit();
114|          }}
115|        >
116|          Read with soundtrack
117|        </button>
118|      </div>
119|    </div>
120|  );
121|}

