1|// @vitest-environment jsdom
2|// Idle keybox: the BYOK pick reveals a password field with a show/hide
3|// eye, the Free pick hides and clears it, and a typed key prefills
4|// ByokStep through initialKey. The key never touches storage.
5|import { act } from "react";
6|import { createRoot, type Root } from "react-dom/client";
7|import { afterEach, beforeEach, describe, expect, test } from "vitest";
8|import { UploadSection } from "./upload";
9|import { ByokStep } from "./byok";
10|
11|(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
12|
13|let container: HTMLDivElement;
14|let root: Root | null = null;
15|
16|function render(node: React.ReactNode) {
17|  act(() => {
18|    root?.render(node);
19|  });
20|}
21|
22|function click(el: Element) {
23|  act(() => {
24|    el.dispatchEvent(new MouseEvent("click", { bubbles: true }));
25|  });
26|}
27|
28|function typeInto(el: HTMLInputElement, value: string) {
29|  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value")?.set;
30|  act(() => {
31|    setter?.call(el, value);
32|    el.dispatchEvent(new Event("input", { bubbles: true }));
33|  });
34|}
35|
36|function pickButton(label: string): HTMLButtonElement {
37|  const found = [...container.querySelectorAll(".ob-pickbtn")].find((el) =>
38|    el.textContent?.includes(label),
39|  );
40|  if (!found || !(found instanceof HTMLButtonElement)) throw new Error(`pick missing: ${label}`);
41|  return found;
42|}
43|
44|function keyInput(): HTMLInputElement {
45|  const el = container.querySelector("#obKey");
46|  if (!(el instanceof HTMLInputElement)) throw new Error("key field missing");
47|  return el;
48|}
49|
50|function eyeButton(): HTMLButtonElement {
51|  const el = [...container.querySelectorAll("button")].find((b) => b.classList.contains("ob-eye"));
52|  if (!el || !(el instanceof HTMLButtonElement)) throw new Error("eye button missing");
53|  return el;
54|}
55|
56|beforeEach(() => {
57|  try {
58|    window.localStorage.clear();
59|  } catch {
60|    // jsdom without storage: the components tolerate it.
61|  }
62|  document.body.innerHTML = "";
63|  container = document.createElement("div");
64|  document.body.appendChild(container);
65|  act(() => {
66|    root = createRoot(container);
67|  });
68|  render(<UploadSection />);
69|});
70|
71|afterEach(() => {
72|  act(() => {
73|    root?.unmount();
74|  });
75|  root = null;
76|  container.remove();
77|});
78|
79|describe("idle keybox", () => {
80|  test("key pick reveals the field with safe attributes", () => {
81|    expect(container.querySelector("#obKeybox")?.hasAttribute("hidden")).toBe(true);
82|    click(pickButton("Bring your own key!"));
83|    expect(container.querySelector("#obKeybox")?.hasAttribute("hidden")).toBe(false);
84|    const input = keyInput();
85|    expect(input.type).toBe("password");
86|    expect(input.placeholder).toBe("Paste your API key");
87|    expect(input.getAttribute("autocomplete")).toBe("off");
88|    expect(input.getAttribute("spellcheck")).toBe("false");
89|    expect(input.name).not.toMatch(/api.?key/i);
90|    expect(eyeButton().getAttribute("aria-label")).toBe("Show API key");
91|  });
92|
93|  test("eye toggles input type and label", () => {
94|    click(pickButton("Bring your own key!"));
95|    click(eyeButton());
96|    expect(keyInput().type).toBe("text");
97|    expect(eyeButton().getAttribute("aria-label")).toBe("Hide API key");
98|    expect(eyeButton().getAttribute("aria-pressed")).toBe("true");
99|    click(eyeButton());
100|    expect(keyInput().type).toBe("password");
101|    expect(eyeButton().getAttribute("aria-label")).toBe("Show API key");
102|  });
103|
104|  test("free pick hides and clears the key", () => {
105|    click(pickButton("Bring your own key!"));
106|    typeInto(keyInput(), "[REDACTED]");
107|    expect(keyInput().value).toBe("[REDACTED]");
108|    click(pickButton("Free"));
109|    expect(container.querySelector("#obKeybox")?.hasAttribute("hidden")).toBe(true);
110|    click(pickButton("Bring your own key!"));
111|    expect(keyInput().value).toBe("");
112|    expect(keyInput().type).toBe("password");
113|    try {
114|      const stored = JSON.stringify(window.localStorage);
115|      expect(stored).not.toContain("[REDACTED]");
116|    } catch {
117|      // No storage in this runner: nothing could have been stored.
118|    }
119|  });
120|});
121|
122|describe("ByokStep initialKey", () => {
123|  test("prefills the key input", () => {
124|    render(<ByokStep reason="too_long" initialKey="[REDACTED]" onSubmit={() => {}} />);
125|    const input = container.querySelector('input[name="transient-key"]');
126|    if (!(input instanceof HTMLInputElement)) throw new Error("byok key input missing");
127|    expect(input.value).toBe("[REDACTED]");
128|  });
129|});

