/* Folio shell: top line, three columns, bottom band. The body never
scrolls at desktop size; the reading column scrolls inside itself. */

.folio {
  --pane-w: 320px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px 40px 24px;
  height: 100vh;
  height: 100dvh;
  display: grid;
  grid-template-columns: var(--pane-w) 12px minmax(0, 1fr) 200px;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas:
    "top top top top"
    "pane div pager margin"
    "pane div read margin"
    "play play play play";
}

.top-line {
  grid-area: top;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--color-text);
}

.wordmark {
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  white-space: nowrap;
}

.wordmark em {
  font-style: normal;
}

.top-center {
  flex: 1;
  text-align: center;
  font-family: var(--font-ui);
  font-size: 12.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chapter-jump {
  position: relative;
  display: inline-block;
}

.chapter-jump-text {
  color: var(--color-text-muted);
  letter-spacing: 0.08em;
}

.chapter-jump select {
  position: absolute;
  inset: 0;
  width: 100%;
  opacity: 0;
  cursor: pointer;
  font-size: 12.5px;
}

.chapter-jump:hover .chapter-jump-text {
  color: var(--color-accent);
}

.chapter-jump:focus-within .chapter-jump-text {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.theme-btn {
  width: 34px;
  height: 34px;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  color: var(--color-text);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex: none;
}

.theme-btn:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.theme-btn svg {
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
}

.theme-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.pane-divider {
  grid-area: div;
  position: relative;
  cursor: col-resize;
  display: flex;
  justify-content: center;
}

