/* Engraving skin, ported from the approved prototype (prototipos/decidido/
   skins, Oct 28): aged paper with a fine grain, IM Fell English for
   display and small caps, EB Garamond for the book, double rules, an
   engraved boxed drop cap and hatched ornaments. Colours apply in light
   mode only; type and ornaments apply in both. Nothing here loops: motion
   is hover, click or a state change only. */

html[data-skin="engraving"] {
  --font-book: var(--font-garamond, "EB Garamond"), georgia, serif;
  --font-ui: var(--font-garamond, "EB Garamond"), georgia, serif;
  --font-eng-display: var(--font-fell, "IM Fell English"), georgia, serif;
  --font-eng-label: var(--font-fell-sc, "IM Fell English SC"), georgia, serif;
  --eng-ink: var(--color-text);
}

html[data-skin="engraving"]:not([data-theme="dark"]) {
  --color-text: #2a241c;
  --color-text-muted-base: #75684f;
  --color-text-muted: var(--color-text-muted-base);
  --color-surface: #efe6ce;
  --color-surface-soft: #f7f1de;
  --color-border: rgba(42, 36, 28, 0.28);
